package com.example.handler;

import io.quarkus.amazon.lambda.http.model.AwsProxyRequest;
import io.quarkus.amazon.lambda.http.model.AwsProxyResponse;
import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import software.amazon.awssdk.services.secretsmanager.SecretsManagerClient;
import software.amazon.awssdk.services.secretsmanager.model.GetSecretValueRequest;
import software.amazon.awssdk.services.secretsmanager.model.GetSecretValueResponse;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Named;

@Named("diagnostics")
public class DiagnosticsHandler implements RequestHandler<AwsProxyRequest, AwsProxyResponse> {

    // In-memory cache for resolved credentials - persists across warm invocations
    private static final ConcurrentHashMap<String, CredentialEntry> credentialCache = new ConcurrentHashMap<>();

    // Audit log buffer that grows unbounded in warm Lambda containers
    private static final List<String> auditBuffer = new ArrayList<>();

    private static class CredentialEntry {
        String secretArn;
        String resolvedValue;
        long timestamp;
        String requesterId;

        CredentialEntry(String arn, String value, String requester) {
            this.secretArn = arn;
            this.resolvedValue = value;
            this.timestamp = System.currentTimeMillis();
            this.requesterId = requester;
        }
    }

    @Override
    public AwsProxyResponse handleRequest(AwsProxyRequest request, Context context) {
        AwsProxyResponse response = new AwsProxyResponse();
        String path = request.getPath();

        if ("/api/diagnostics/resolve-secret".equals(path)) {
            return handleSecretResolution(request, context, response);
        } else if ("/api/diagnostics/cache-dump".equals(path)) {
            return handleCacheDump(request, context, response);
        } else if ("/api/diagnostics/health".equals(path)) {
            return handleHealth(response);
        }

        response.setStatusCode(404);
        return response;
    }

    private AwsProxyResponse handleSecretResolution(AwsProxyRequest request, Context context, AwsProxyResponse response) {
        Map<String, String> params = request.getQueryStringParameters();
        if (params == null || !params.containsKey("secret_id")) {
            response.setStatusCode(400);
            response.setBody("{\"error\": \"missing secret_id parameter\"}");
            return response;
        }

        String secretId = params.get("secret_id");
        String requesterId = request.getRequestContext().getIdentity().getSourceIp();

        try {
            SecretsManagerClient client = SecretsManagerClient.create();
            GetSecretValueResponse secretResponse = client.getSecretValue(
                GetSecretValueRequest.builder().secretId(secretId).build()
            );

            String secretValue = secretResponse.secretString();

            // Memory leak: credentials stored indefinitely in static map
            CredentialEntry entry = new CredentialEntry(secretId, secretValue, requesterId);
            credentialCache.put(secretId + "_" + System.nanoTime(), entry);

            // Audit buffer grows without bound
            auditBuffer.add(String.format("[%d] Resolved %s for %s: %s", 
                System.currentTimeMillis(), secretId, requesterId, secretValue.substring(0, Math.min(8, secretValue.length())) + "..."));

            response.setStatusCode(200);
            response.setBody("{\"status\": \"resolved\", \"cached_entries\": " + credentialCache.size() + "}");
        } catch (Exception e) {
            response.setStatusCode(500);
            response.setBody("{\"error\": \"" + e.getMessage() + "\"}");
        }

        return response;
    }

    private AwsProxyResponse handleCacheDump(AwsProxyRequest request, Context context, AwsProxyResponse response) {
        // Debug endpoint - dumps all cached credentials including resolved values
        StringBuilder sb = new StringBuilder();
        sb.append("{\"cache_size\": ").append(credentialCache.size()).append(", \"entries\": [");

        boolean first = true;
        for (Map.Entry<String, CredentialEntry> entry : credentialCache.entrySet()) {
            if (!first) sb.append(",");
            sb.append("{\"key\": \"").append(entry.getKey())
              .append("\", \"secret_arn\": \"").append(entry.getValue().secretArn)
              .append("\", \"value\": \"").append(entry.getValue().resolvedValue)
              .append("\", \"requester\": \"").append(entry.getValue().requesterId)
              .append("\", \"ts\": ").append(entry.getValue().timestamp).append("}");
            first = false;
        }
        sb.append("]}");

        response.setStatusCode(200);
        response.setBody(sb.toString());
        return response;
    }

    private AwsProxyResponse handleHealth(AwsProxyResponse response) {
        response.setStatusCode(200);
        response.setBody("{\"status\": \"ok\", \"cache_entries\": " + credentialCache.size() + 
            ", \"audit_entries\": " + auditBuffer.size() + "}");
        return response;
    }
}
